/* MegMultiMedia — studio portfolio. Content and contact configuration live in content.js. */
const config=window.MMM||{images:{},email:'',whatsapp:''};
const path=location.pathname.replace(/\/$/,'')||'/';
const main=document.querySelector('main');
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const routeNames={'/':'Creative production & digital experiences','/work':'The portfolio','/video-photo':'Production','/web-development':'Digital experiences','/business-growth':'Business growth','/about':'The studio','/contact':'Start a project'};
document.title=`${routeNames[path]||'Page not found'} — MegMultiMedia`;
const arrow='<svg width="16" height="16" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M5 19 19 5M5 5h14v14" stroke="currentColor" stroke-width="1.5"/></svg>';
const link=(href,label,kind='text-link')=>`<a class="${kind}" href="${href}"><span>${label}</span>${arrow}</a>`;
const tag=(n,text)=>`<div class="section-tag"><span>${n} / ${text}</span><span>MEGMULTIMEDIA®</span></div>`;
const stockNote='<span class="stock-label">ILLUSTRATIVE PHOTOGRAPHY</span>';
const photo=(key,alt,extra='')=>`<img src="${config.images[key]}" alt="${alt}" loading="lazy" ${extra}>`;
const menu=document.querySelector('.menu');
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close menu':'Open menu');document.querySelector('nav').classList.toggle('open',open);document.body.classList.toggle('menu-open',open)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open menu');document.querySelector('nav').classList.remove('open');document.body.classList.remove('menu-open')}});
document.querySelectorAll('nav a').forEach(a=>{if(a.getAttribute('href')===path)a.setAttribute('aria-current','page')});
const title=(eyebrow,heading,description='')=>`<section class="page-heading wrap"><span class="eyebrow">${eyebrow}</span><h1 data-text-reveal>${heading}</h1><div class="heading-bottom">${description?`<p>${description}</p>`:''}<span class="heading-mark" aria-hidden="true">✳</span></div></section>`;
const cta=(heading='Have something<br><i>in mind?</i>')=>`<section class="cta"><div class="wrap"><span class="eyebrow">THE NEXT CHAPTER</span><div class="cta-layout"><h2 data-text-reveal>${heading}</h2><div><p>A brand. A film. A digital experience.<br/>Let’s find your next possibility.</p>${link('/contact','Start a project','button')}${config.whatsapp?`<a class="text-link" href="https://wa.me/${config.whatsapp.replace(/\D/g,'')}" target="_blank" rel="noopener">WhatsApp us ${arrow}</a>`:''}</div></div><div class="cta-baseline"><span>CREATIVE THINKING. CONSIDERED EXECUTION.</span><span>CREATE / BUILD / GROW</span></div></div></section>`;
const hero=()=>`<section class="hero"><div class="wrap hero-copy"><span class="eyebrow"><b class="status-dot"></b> INDEPENDENT CREATIVE & DIGITAL STUDIO</span><h1 data-text-reveal>MegMultiMedia<span>.</span></h1><div class="hero-intro"><p>We create what moves you.<br/><span>We build what moves you forward.</span></p>${link('/work','Discover our work','button light')}</div></div><div class="wrap hero-experience" data-depth><div class="hero-media"><img src="/assets/production.jpg" alt="Cinema production set — illustrative photography" fetchpriority="high" width="1200" height="800"/><div class="hero-shade"></div><div class="hero-media-copy"><span>IDEA → EXPERIENCE</span><h2>Every detail.<br/>A different perspective.</h2>${link('/video-photo','Behind the craft')}</div><div class="hero-media-index"><span>MMM / PRODUCTION</span><span>01 — 03</span></div></div><div class="hero-media-tabs" role="group" aria-label="Explore creative disciplines">${[['production','Production'],['product','Photography'],['food','Visual direction']].map(([key,label],i)=>`<button data-hero-media="${key}" aria-pressed="${i===0}"><span>0${i+1}</span>${label}<i></i></button>`).join('')}</div></div><div class="wrap hero-baseline"><a href="#selected-work">SCROLL TO EXPLORE <span>↓</span></a><span>CREATIVE / PRODUCTION / DIGITAL / GROWTH</span></div></section>`;
const statement=()=>`<section class="section statement">${tag('STUDIO','ONE CONNECTED POINT OF VIEW')}<div class="statement-grid"><h2 data-text-reveal>Different disciplines.<br/>One <i>shared ambition.</i></h2><div><p>Great work happens when creative thinking, production and digital strategy come together. We connect the dots, from the first idea to the final experience.</p>${link('/about','Inside the studio')}</div></div></section>`;
const projectCard=(key,name,category,n,wide=false)=>`<button class="project ${wide?'wide':''}" data-project="${key}" aria-label="View ${name} illustrative photograph"><div class="project-image" data-depth>${photo(key,name+' — illustrative stock photograph')}${stockNote}<span class="view-project">${arrow}</span><span class="project-no">${n} / VISUAL STUDY</span></div><div class="project-caption"><div><span>${category}</span><h3>${name}</h3></div><span>Explore ${arrow}</span></div></button>`;
const work=(full=false)=>`<section class="section work-section" id="selected-work">${tag('01','THE VISUAL COLLECTION')}<div class="section-heading"><h2 data-text-reveal>Work that makes<br><i>you feel something.</i></h2>${link('/work','View the collection')}</div><p class="editorial-note">A visual direction collection using illustrative stock photography. Client films and photography will follow.</p><div class="project-grid">${projectCard('product','Light. Texture. Feeling.','PRODUCT / PHOTOGRAPHY','01',true)}${projectCard('food','A moment, made vivid.','FOOD & DRINK / VISUAL DIRECTION','02')}${projectCard('production','The story behind the frame.','PRODUCTION / ON SET','03')}</div></section>`;
const serviceData=[['Creative','Find a point of view worth noticing.',['Scriptwriting','Creative direction','Content strategy'],'From the story and the audience to the visual language, we shape a clear direction for everything that follows.','/work'],['Production','Make the idea feel real.',['Videography','Photography','Video production','Video editing'],'Camera, lighting, composition and editing. Deliberate craft that brings a brand’s story into focus.','/video-photo'],['Digital','Build a better brand experience.',['Website development','Social media management','SEO'],'Thoughtful websites and digital touchpoints that connect a brand’s identity with the people who matter.','/web-development'],['Growth','Turn attention into opportunity.',['Influencer marketing','Meta Ads','Google Ads','Performance marketing','PR'],'Creative distribution, audience development and ongoing learning, connected to the ambitions of your business.','/business-growth']];
const services=()=>`<section class="services-surface"><div class="section capabilities">${tag('02','OUR CAPABILITIES')}<div class="capabilities-layout"><div><h2 data-text-reveal>From a spark.<br/><i>To something<br/>significant.</i></h2><p>One studio, with the disciplines<br/>to bring the whole idea together.</p></div><div class="service-list">${serviceData.map((s,i)=>`<details ${i===0?'open':''}><summary><span class="service-index">0${i+1}</span><h3>${s[0]}</h3><span class="plus">+</span></summary><div class="service-content"><h4>${s[1]}</h4><p>${s[3]}</p><ul>${s[2].map(x=>`<li>${x}</li>`).join('')}</ul>${link(s[4],'Explore '+s[0].toLowerCase())}</div></details>`).join('')}</div></div></div></section>`;
const growthServices=[['Influencer marketing','Bring your brand into conversations that resonate.'],['Meta ads','Connect considered creative with relevant audiences.'],['Google ads','Meet people when they are actively looking.'],['SEO','Build discoverability into your digital presence.'],['Social media','Develop a consistent voice and a connected community.'],['PR & press releases','Shape a story worth sharing.']];
const dashboard=()=>`<div class="growth-console"><div class="console-top"><span><b class="status-dot"></b> MMM / GROWTH STUDIO</span><span>THE APPROACH</span></div><div class="growth-steps" role="tablist" aria-label="Growth stages">${['Creativity','Attention','Audience','Performance','Growth'].map((x,i)=>`<button role="tab" id="stage-${i}" aria-selected="${i===0}" tabindex="${i===0?0:-1}" aria-controls="stage-panel" data-stage="${i}">${x}</button>`).join('')}</div><div id="stage-panel" role="tabpanel" aria-labelledby="stage-0" tabindex="0"><span class="stage-counter">01</span><h3 id="stage-title">CREATIVITY</h3><p id="stage-copy"></p><div class="stage-deliverables"></div><div class="growth-path" aria-hidden="true"><svg viewBox="0 0 520 115" preserveAspectRatio="none"><path class="path-grid" d="M0 28H520M0 58H520M0 88H520"/><path class="path-line" d="M0 95C60 95 50 72 100 72S140 83 190 55 230 70 280 42 340 57 390 20 460 30 520 5"/></svg><span>CREATE</span><span>CONNECT</span><span>REFINE</span></div></div><div class="metrics-heading"><span>WHAT WE MEASURE</span><span>FRAMEWORK PREVIEW</span></div><div class="metrics">${['REACH','ENGAGEMENT','LEADS','CTR','CPL','CONVERSIONS','ROAS','RETENTION'].map(x=>`<span>${x}<b>—</b><small>Awaiting data</small></span>`).join('')}</div><p class="console-note">Illustrative strategy diagram. No live campaign figures.</p></div>`;
const growth=(full=false)=>`<section class="section growth-section">${tag('03','CREATIVE MEETS PERFORMANCE')}<div class="growth-layout"><div><h2 data-text-reveal>Attention is<br/>a beginning.<br/><i>Make it matter.</i></h2><p>Build the audience. Create the opportunity.<br/>Learn from what happens next.</p>${link('/business-growth','Explore growth')}</div>${dashboard()}</div>${full?`<div class="growth-offerings">${growthServices.map((s,i)=>`<article><span>0${i+1}</span><h3>${s[0]}</h3><p>${s[1]}</p></article>`).join('')}</div>`:''}</section>`;
const bts=()=>`<section class="production-surface"><div class="section bts">${tag('04','THE CRAFT BEHIND THE CONTENT')}<div class="bts-grid"><div class="bts-photo" data-depth>${photo('production','Cinema production set — illustrative photography')}${stockNote}</div><div class="bts-copy"><span class="eyebrow">DIRECTION / PRODUCTION / POST</span><h2 data-text-reveal>Every frame.<br/><i>Considered.</i></h2><p>A clear direction. The right light.<br/>The final details that make it feel complete.</p><div class="process"><span>01 / DIRECTION</span><span>02 / PRODUCTION</span><span>03 / POST</span></div>${link('/video-photo','Explore production')}</div></div></div></section>`;
const websiteProjects=[{name:'The Lucid Sway',url:'https://thelucidsway.com/',desktop:'/assets/lucidsway-desktop.png',mobile:'/assets/lucidsway-mobile.png'}];
const websiteCards=()=>websiteProjects.map((project,i)=>`<article class="website-showcase" data-website="${i}"><div class="website-toolbar"><div><span class="eyebrow">DESIGN / DEVELOPMENT</span><h3>${project.name}</h3></div><div class="preview-toggle" role="group" aria-label="Preview device"><button type="button" data-view="desktop" aria-pressed="true">Desktop</button><button type="button" data-view="mobile" aria-pressed="false">Mobile</button></div></div><div class="website-device-stage"><a class="website-device" data-depth href="${project.url}" target="_blank" rel="noopener" aria-label="Visit ${project.name} live website"><div class="website-chrome" aria-hidden="true"><span class="chrome-dots">● ● ●</span><span>thelucidsway.com</span><span>↗</span></div><div class="website-screen"><img src="${project.desktop}" alt="${project.name} desktop website preview" loading="lazy" width="1440" height="1000"></div></a></div><a class="website-live-link" href="${project.url}" target="_blank" rel="noopener">Visit live website ${arrow}</a></article>`).join('');
const websiteShowcase=()=>`<section class="section built-websites" id="website-showcase">${tag('05','DIGITAL EXPERIENCES')}<div class="section-heading"><h2 data-text-reveal>Designed to feel right.<br/><i>Built to work beautifully.</i></h2>${link('/web-development','Explore digital')}</div><div class="website-portfolio-grid">${websiteCards()}</div></section>`;
const digital=(full=false)=>`<section class="section digital"><div class="digital-layout"><h2 data-text-reveal>A better experience.<br/><i>In every detail.</i></h2><p>Distinctive design, thoughtful interactions and reliable development. A digital presence that feels like your brand.</p></div><div class="approach-line">${[['Design','A clear visual direction.'],['Development','Considered interactions.'],['Mobile','Every screen, refined.'],['SEO','Structure and discoverability.'],['Launch','A complete final review.']].map(([x,d],i)=>`<div><small>0${i+1}</small><h3>${x}</h3><p>${d}</p></div>`).join('')}</div></section>`;
const about=()=>`<section class="section about-strip">${tag('06','THE STUDIO')}<div class="about-grid"><h2 data-text-reveal>Independent minds.<br/><i>Connected possibilities.</i></h2><div><p class="large-copy">Content production, digital experiences and business growth. Different perspectives, brought together under one roof.</p>${link('/about','Meet MegMultiMedia')}</div></div></section>`;
if(path==='/')main.innerHTML=hero()+statement()+work()+services()+growth()+bts()+websiteShowcase()+about()+cta();
else if(path==='/work')main.innerHTML=title('WORK / THE PORTFOLIO','Ideas you can feel.<br/><i>Work you remember.</i>','A collection of visual directions, production and digital experiences.')+work(true)+websiteShowcase()+cta();
else if(path==='/video-photo')main.innerHTML=title('PRODUCTION / VIDEO + PHOTOGRAPHY','Stories worth<br/><i>stopping for.</i>','Emotion in every frame. Intention in every detail.')+`<section class="section production-gallery"><div class="section-heading"><h2 data-text-reveal>A different way<br/><i>of seeing.</i></h2><span class="eyebrow">THE VISUAL COLLECTION</span></div><p class="editorial-note">Illustrative stock photography. Client films and behind-the-scenes footage will follow.</p><div class="horizontal-gallery">${projectCard('food','A moment, made vivid.','FOOD & DRINK','01')}${projectCard('product','Light. Texture. Feeling.','PRODUCT','02')}${projectCard('production','Behind the frame.','PRODUCTION','03')}</div></section>`+bts()+`<section class="section equipment">${tag('TOOLS','BEHIND THE CRAFT')}<div>${['Sony α7R V','GM lenses','Lumix S1H','Godox lighting','Gimbals','Tripods'].map(x=>`<span>${x}</span>`).join('')}</div></section>`+cta('Your brand.<br/><i>In a new light.</i>');
else if(path==='/web-development')main.innerHTML=title('DIGITAL / DESIGN + DEVELOPMENT','Considered design.<br/><i>Effortless experiences.</i>','A digital presence that feels like your brand, down to the smallest interaction.')+websiteShowcase()+digital(true)+cta('A new chapter<br/><i>for your digital world.</i>');
else if(path==='/business-growth')main.innerHTML=title('GROWTH / STRATEGY + PERFORMANCE','Creative opens doors.<br/><i>Strategy moves forward.</i>','Build the audience. Create the opportunity. Measure what matters.')+growth(true)+`<section class="section growth-manifesto"><h2 data-text-reveal>Make the content.<br/><i>Build the audience.</i><br/>Measure the growth.</h2></section>`+cta();
else if(path==='/about')main.innerHTML=title('STUDIO / OUR POINT OF VIEW','Independent minds.<br/><i>Connected by creativity.</i>','MegMultiMedia brings production, digital experiences and business growth together under one roof.')+`<section class="section about-page"><div class="about-grid"><div class="about-logo"><img src="/assets/mmm-logo-transparent.png" alt="MegMultiMedia logo" width="746" height="335"/></div><div><span class="eyebrow">WHY WE COME TOGETHER</span><h2 data-text-reveal>A story needs craft.<br/><i>A brand needs direction.</i></h2><p class="large-copy">We bring different disciplines into the same conversation, so every idea can become a more complete experience.</p></div></div><div class="approach-line">${[['Strategy','Find the audience and point of view.'],['Create','Bring the direction to life.'],['Distribute','Meet the right people.'],['Optimize','Learn. Refine. Move forward.']].map(([x,d],i)=>`<div><small>0${i+1}</small><h3>${x}</h3><p>${d}</p></div>`).join('')}</div><div class="founder"><div class="founder-photo" data-depth><img class="founder-portrait" src="/assets/rithwik-pemmada.png" alt="Rithwik Pemmada, Managing Director of MegMultiMedia" loading="lazy" width="864" height="1090"/></div><div class="founder-bio"><span class="eyebrow">THE PERSON BEHIND THE STUDIO</span><h2 data-text-reveal>Rithwik<br/><i>Pemmada.</i></h2><p>Managing Director</p>${link('/contact','Start a conversation')}</div></div></section>`+cta('Good work starts<br/><i>with good people.</i>');
else if(path==='/contact')main.innerHTML=title('CONTACT / THE NEXT CONVERSATION','Have a project<br/><i>in mind?</i>','Tell us what you’re thinking. We’ll take it from there.')+`<section class="section contact-layout"><div class="contact-copy"><h2>A good conversation.<br/><i>A great starting point.</i></h2><p>A brand, a campaign, a website or an idea that doesn’t fit in a box. We’d like to hear it.</p><div class="contact-note"><span class="eyebrow">ENQUIRY PREVIEW</span><p>Prepare and download your project brief. Contact delivery is not connected yet; nothing is sent from this preview.</p></div></div><form id="enquiry"><div class="form-row"><label>Your name<input name="name" autocomplete="name" required maxlength="100" placeholder="Full name"/></label><label>Business name<input name="business" autocomplete="organization" maxlength="150" placeholder="Your brand or business"/></label></div><div class="form-row"><label>Email<input name="email" type="email" autocomplete="email" required maxlength="150" placeholder="you@company.com"/></label><label>Phone<input name="phone" type="tel" autocomplete="tel" maxlength="30" placeholder="Include country code"/></label></div><fieldset><legend>What can we help with?</legend><div class="service-choices">${['Creative','Video & Photography','Website Development','Social Media','Business Growth','Other'].map(x=>`<label><input type="checkbox" name="services" value="${x}"/><span>${x}</span></label>`).join('')}</div></fieldset><label>Project details<textarea name="details" rows="5" required minlength="10" maxlength="5000" placeholder="Your idea, goals and timeline…"></textarea></label><button class="button" type="submit">Prepare project brief ${arrow}</button><p class="form-privacy">Your details stay in this browser. They are not submitted.</p><div id="form-result" aria-live="polite"></div></form></section>`;
else main.innerHTML=title('404','A little<br/><i>off course.</i>')+`<section class="section">${link('/','Back to home','button')}</section>`;
// Hero media selector: explicit controls, no automatic carousel.
const heroCopy={production:['Every detail.<br/>A different perspective.','/video-photo','Behind the craft'],product:['Light. Texture.<br/>A feeling that stays.','/work','Explore photography'],food:['Make the everyday.<br/>Extraordinary.','/work','Explore visual direction']};
document.querySelectorAll('[data-hero-media]').forEach(button=>button.addEventListener('click',()=>{const key=button.dataset.heroMedia,img=document.querySelector('.hero-media>img');if(button.getAttribute('aria-pressed')==='true')return;document.querySelectorAll('[data-hero-media]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));img.src=config.images[key];img.alt=key+' — illustrative stock photography';document.querySelector('.hero-media-index').innerHTML=`<span>MMM / ${button.textContent.trim().replace(/^0\d/, '').trim().toUpperCase()}</span><span>0${['production','product','food'].indexOf(key)+1} — 03</span>`;const [heading,href,label]=heroCopy[key];document.querySelector('.hero-media-copy h2').innerHTML=heading;document.querySelector('.hero-media-copy .text-link').outerHTML=link(href,label);if(!reduced&&!document.documentElement.classList.contains('motion-disabled'))img.animate([{opacity:.2,transform:'scale(1.06)'},{opacity:1,transform:'scale(1)'}],{duration:700,easing:'cubic-bezier(.22,1,.36,1)'});}));
const stageTexts=[
['CREATIVITY','Shape the idea, message and visual direction that give your brand a recognisable voice.',['Creative direction','Content strategy'],['ENGAGEMENT']],
['ATTENTION','Put the story in front of the right people through content, distribution and paid campaigns.',['Social content','Paid distribution'],['REACH','CTR']],
['AUDIENCE','Build a relevant audience and understand which messages create meaningful interest.',['Audience insights','Community building'],['ENGAGEMENT','LEADS']],
['PERFORMANCE','Review campaign signals to improve the journey from first click to enquiry or purchase.',['Campaign analysis','Conversion optimisation'],['CPL','CONVERSIONS','ROAS']],
['GROWTH','Use what works to guide the next campaign and strengthen long-term customer relationships.',['Ongoing optimisation','Retention strategy'],['ROAS','RETENTION']]];
function setStage(button){const n=Number(button.dataset.stage);document.querySelectorAll('[data-stage]').forEach(b=>{b.setAttribute('aria-selected',b===button);b.tabIndex=b===button?0:-1});document.querySelector('#stage-panel').setAttribute('aria-labelledby',button.id);document.querySelector('#stage-title').innerHTML=stageTexts[n][0];document.querySelector('#stage-copy').textContent=stageTexts[n][1];document.querySelector('.stage-counter').textContent=`0${n+1}`;document.querySelector('.growth-console').style.setProperty('--stage',n);const deliverables=document.querySelector('.stage-deliverables');deliverables.replaceChildren(...stageTexts[n][2].map(text=>{const span=document.createElement('span');span.textContent=text;return span}));document.querySelectorAll('.metrics>span').forEach(metric=>metric.classList.toggle('metric-relevant',stageTexts[n][3].includes(metric.firstChild.textContent)));}
document.querySelectorAll('[data-stage]').forEach(b=>{b.addEventListener('click',()=>setStage(b));b.addEventListener('keydown',e=>{const tabs=[...document.querySelectorAll('[data-stage]')];let i=tabs.indexOf(b);if(e.key==='ArrowRight')i=(i+1)%tabs.length;else if(e.key==='ArrowLeft')i=(i-1+tabs.length)%tabs.length;else if(e.key==='Home')i=0;else if(e.key==='End')i=tabs.length-1;else return;e.preventDefault();tabs[i].focus();setStage(tabs[i])})});
const dialog=document.createElement('dialog');dialog.className='lightbox';dialog.setAttribute('aria-label','Photograph preview');dialog.innerHTML='<button class="close-dialog" aria-label="Close image">×</button><img alt=""><p></p>';document.body.append(dialog);let lastProject;
document.querySelectorAll('[data-project]').forEach(b=>b.addEventListener('click',()=>{lastProject=b;dialog.querySelector('img').src=config.images[b.dataset.project];dialog.querySelector('img').alt=b.querySelector('img').alt;dialog.querySelector('p').textContent=b.querySelector('h3').textContent+' — illustrative stock photography';dialog.showModal()}));
function closeDialog(){dialog.close();lastProject?.focus()}dialog.querySelector('button').addEventListener('click',closeDialog);dialog.addEventListener('click',e=>{if(e.target===dialog)closeDialog()});
let briefUrl;const form=document.querySelector('#enquiry');if(form)form.addEventListener('submit',e=>{e.preventDefault();const d=new FormData(form);const brief=`MEGMULTIMEDIA — PROJECT ENQUIRY\n\nName: ${d.get('name')}\nBusiness: ${d.get('business')}\nEmail: ${d.get('email')}\nPhone: ${d.get('phone')}\nServices: ${d.getAll('services').join(', ')||'To discuss'}\n\nPROJECT DETAILS\n${d.get('details')}\n`;const result=document.querySelector('#form-result');result.replaceChildren();const p=document.createElement('p');p.textContent='Your brief is ready. Download it to keep a copy. Nothing has been sent.';const download=document.createElement('a');download.className='button';download.textContent='DOWNLOAD BRIEF ↓';download.download='MMM-project-enquiry.txt';if(briefUrl)URL.revokeObjectURL(briefUrl);briefUrl=URL.createObjectURL(new Blob([brief],{type:'text/plain'}));download.href=briefUrl;result.append(p,download);download.focus()});

// Decode both views in advance so the device transition never waits for an image.
websiteProjects.forEach(project=>[project.desktop,project.mobile].forEach(src=>{const image=new Image();image.src=src;image.decode?.().catch(()=>{})}));
document.querySelectorAll('.preview-toggle button').forEach(button=>button.addEventListener('click',async()=>{
 const showcase=button.closest('.website-showcase'),project=websiteProjects[Number(showcase.dataset.website)],phone=button.dataset.view==='mobile';
 const request=(showcase.previewRequest||0)+1;showcase.previewRequest=request;
 const demo=showcase.classList.contains('mmm-device-demo');
 if(!demo){const preload=new Image();preload.src=phone?project.mobile:project.desktop;try{await preload.decode()}catch{}if(showcase.previewRequest!==request)return}
 showcase.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));
 const device=showcase.querySelector('.website-device'),img=device.querySelector('img');
 const before=device.getBoundingClientRect();device.getAnimations().forEach(a=>a.cancel());img.getAnimations().forEach(a=>a.cancel());
 device.classList.toggle('is-mobile',phone);
 if(!demo){img.src=phone?project.mobile:project.desktop;img.alt=project.name+(phone?' mobile':' desktop')+' website preview';img.width=phone?390:1440;img.height=phone?844:1000}
 const after=device.getBoundingClientRect();
 if(!matchMedia('(prefers-reduced-motion: reduce)').matches&&!document.documentElement.classList.contains('motion-disabled')){
 device.animate([{width:before.width+'px',height:before.height+'px'},{width:after.width+'px',height:after.height+'px'}],{duration:650,easing:'cubic-bezier(.22,1,.36,1)'});
 img.animate([{opacity:0,filter:'blur(3px)'},{opacity:1,filter:'blur(0)'}],{duration:550,easing:'ease-out'});
 }
}));

const initialStage=document.querySelector('[data-stage="0"]');if(initialStage)setStage(initialStage);
